      if (groupKeys != null) 'group_keys': groupKeys,
      if (answer != null) 'answer': answer,
      if (model != null) 'model': model,
      if (createdAt != null) 'created_at': createdAt,
      if (rowid != null) 'rowid': rowid,
    });
