      month: month ?? this.month,
      inputHash: inputHash ?? this.inputHash,
      groupKeys: groupKeys ?? this.groupKeys,
      answer: answer ?? this.answer,
      model: model ?? this.model,
      createdAt: createdAt ?? this.createdAt,
      rowid: rowid ?? this.rowid,
